mapper.select:
SELECT pay_no, order_no, amount, channel, status,
       external_txn_id, fail_reason, paid_at, created_at
FROM pay_log
WHERE order_no = #{orderNo}
  AND user_id = #{userId}
ORDER BY id DESC

mapper.update:
UPDATE pay_log
SET status          = 1,
    external_txn_id = #{externalTxnId},
    paid_at         = #{paidAt}
WHERE id = #{id}
  AND status = 0

UPDATE pay_log
SET status      = #{status},
    fail_reason = #{reason}
WHERE id = #{id}
  AND status = 0
